window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9f607bf36afa0f30"]={"versions": [{"id": "FIG-9f607bf36afa0f30", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung des BSW-Modulbeschreibungs-Templates (BSW Module Description Template, BSW-MDT) innerhalb der AUTOSAR Classic Platform. Es spezifiziert die strukturelle Einbettung von Namenspräfixen für BSW-Scheduler-Artefakte in Bezug auf das interne Verhalten von Basissoftwaremodulen und deren ausführbare Einheiten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei Metaklassen und deren Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>BswInternalBehavior</code> (spezialisiert die kursiv gesetzte Basisklasse <code>InternalBehavior</code>): Zentraler Container für das interne Modulverhalten.\n</li><li><code>BswModuleEntity</code> (spezialisiert die kursiv gesetzte Basisklasse <code>ExecutableEntity</code>): Repräsentiert ausführbare Funktionseinheiten innerhalb des Moduls.\n</li><li><code>BswSchedulerNamePrefix</code> (spezialisiert die kursiv gesetzte Basisklasse <code>ImplementationProps</code>): Definiert modulspezifische Präfixe für Namen generierter Code-Artefakte an der Schnittstelle zum BSW-Scheduler.\n</li></ul>\n<p class=\"fig-p\">Beziehungen:</p>\n<ul class=\"fig-list\"><li>Komposition von <code>BswInternalBehavior</code> zu <code>BswModuleEntity</code>: Rollenname <code>+entity</code>, Multiplizität <code>1..*</code>, annotiert mit dem Stereotyp <code>«atpVariation»</code>.\n</li><li>Komposition von <code>BswInternalBehavior</code> zu <code>BswSchedulerNamePrefix</code>: Rollenname <code>+schedulerNamePrefix</code>, Multiplizität <code>0..*</code>, annotiert mit dem Stereotyp <code>«atpVariation»</code>.\n</li><li>Unidirektionale Assoziation von <code>BswModuleEntity</code> zu <code>BswSchedulerNamePrefix</code>: Rollenname <code>+schedulerNamePrefix</code>, Multiplizität <code>0..1</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; es stellt keine Laufzeit- oder Sequenzabläufe dar. Es definiert deklarative Kardinalitäten und Zuordnungen, die zur Entwurfszeit und während der Codegenerierung (insbesondere RTE-/BSW-Scheduler-Generierung) ausgewertet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für die AUTOSAR-Modellierung von BSW-Modulbeschreibungen:</p>\n<ul class=\"fig-list\"><li>Ein <code>BswInternalBehavior</code> aggregiert mindestens eine <code>BswModuleEntity</code> (<code>1..*</code>) und optional mehrere <code>BswSchedulerNamePrefix</code>-Definitionen (<code>0..*</code>).\n</li><li>Beide Kompositionen unterliegen der AUTOSAR-Variabilität (<code>«atpVariation»</code>), womit die Aggregationen über Variant-Handling konditioniert werden können.\n</li><li>Eine <code>BswModuleEntity</code> kann optional genau einen spezifischen <code>BswSchedulerNamePrefix</code> (<code>0..1</code>) referenzieren.\n</li><li>BSW-Scheduler-Präfixe dürfen keine nach außen sichtbaren Schnittstellenbezeichner oder Modulkürzel (<code>BswModuleEntry.shortName</code>) überschreiben, sondern dienen der Namensbildung interner Scheduler-Artefakte.\n</li></ul>"}, {"id": "FIG-6fdb09b6d7409adc", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung des BSW-Modulbeschreibungs-Templates (BSW Module Description Template, BSW-MDT) innerhalb der AUTOSAR Classic Platform. Es spezifiziert die strukturelle Einbettung von Namenspräfixen für BSW-Scheduler-Artefakte in Bezug auf das interne Verhalten von Basissoftwaremodulen und deren ausführbare Einheiten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei Metaklassen und deren Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>BswInternalBehavior</code> (spezialisiert die kursiv gesetzte Basisklasse <code>InternalBehavior</code>): Zentraler Container für das interne Modulverhalten.\n</li><li><code>BswModuleEntity</code> (spezialisiert die kursiv gesetzte Basisklasse <code>ExecutableEntity</code>): Repräsentiert ausführbare Funktionseinheiten innerhalb des Moduls.\n</li><li><code>BswSchedulerNamePrefix</code> (spezialisiert die kursiv gesetzte Basisklasse <code>ImplementationProps</code>): Definiert modulspezifische Präfixe für Namen generierter Code-Artefakte an der Schnittstelle zum BSW-Scheduler.\n</li></ul>\n<p class=\"fig-p\">Beziehungen:</p>\n<ul class=\"fig-list\"><li>Komposition von <code>BswInternalBehavior</code> zu <code>BswModuleEntity</code>: Rollenname <code>+entity</code>, Multiplizität <code>1..*</code>, annotiert mit dem Stereotyp <code>«atpVariation»</code>.\n</li><li>Komposition von <code>BswInternalBehavior</code> zu <code>BswSchedulerNamePrefix</code>: Rollenname <code>+schedulerNamePrefix</code>, Multiplizität <code>0..*</code>, annotiert mit dem Stereotyp <code>«atpVariation»</code>.\n</li><li>Unidirektionale Assoziation von <code>BswModuleEntity</code> zu <code>BswSchedulerNamePrefix</code>: Rollenname <code>+schedulerNamePrefix</code>, Multiplizität <code>0..1</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; es stellt keine Laufzeit- oder Sequenzabläufe dar. Es definiert deklarative Kardinalitäten und Zuordnungen, die zur Entwurfszeit und während der Codegenerierung (insbesondere RTE-/BSW-Scheduler-Generierung) ausgewertet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für die AUTOSAR-Modellierung von BSW-Modulbeschreibungen:</p>\n<ul class=\"fig-list\"><li>Ein <code>BswInternalBehavior</code> aggregiert mindestens eine <code>BswModuleEntity</code> (<code>1..*</code>) und optional mehrere <code>BswSchedulerNamePrefix</code>-Definitionen (<code>0..*</code>).\n</li><li>Beide Kompositionen unterliegen der AUTOSAR-Variabilität (<code>«atpVariation»</code>), womit die Aggregationen über Variant-Handling konditioniert werden können.\n</li><li>Eine <code>BswModuleEntity</code> kann optional genau einen spezifischen <code>BswSchedulerNamePrefix</code> (<code>0..1</code>) referenzieren.\n</li><li>BSW-Scheduler-Präfixe dürfen keine nach außen sichtbaren Schnittstellenbezeichner oder Modulkürzel (<code>BswModuleEntry.shortName</code>) überschreiben, sondern dienen der Namensbildung interner Scheduler-Artefakte.\n</li></ul>"}, {"id": "FIG-b81f108b9929e2a3", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung des BSW-Modulbeschreibungs-Templates (BSW Module Description Template, BSW-MDT) innerhalb der AUTOSAR Classic Platform. Es spezifiziert die strukturelle Einbettung von Namenspräfixen für BSW-Scheduler-Artefakte in Bezug auf das interne Verhalten von Basissoftwaremodulen und deren ausführbare Einheiten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei Metaklassen und deren Beziehungen:</p>\n<ul class=\"fig-list\"><li><code>BswInternalBehavior</code> (spezialisiert die kursiv gesetzte Basisklasse <code>InternalBehavior</code>): Zentraler Container für das interne Modulverhalten.\n</li><li><code>BswModuleEntity</code> (spezialisiert die kursiv gesetzte Basisklasse <code>ExecutableEntity</code>): Repräsentiert ausführbare Funktionseinheiten innerhalb des Moduls.\n</li><li><code>BswSchedulerNamePrefix</code> (spezialisiert die kursiv gesetzte Basisklasse <code>ImplementationProps</code>): Definiert modulspezifische Präfixe für Namen generierter Code-Artefakte an der Schnittstelle zum BSW-Scheduler.\n</li></ul>\n<p class=\"fig-p\">Beziehungen:</p>\n<ul class=\"fig-list\"><li>Komposition von <code>BswInternalBehavior</code> zu <code>BswModuleEntity</code>: Rollenname <code>+entity</code>, Multiplizität <code>1..*</code>, annotiert mit den Stereotypen <code>«atpVariation,atpSplitable»</code>.\n</li><li>Komposition von <code>BswInternalBehavior</code> zu <code>BswSchedulerNamePrefix</code>: Rollenname <code>+schedulerNamePrefix</code>, Multiplizität <code>0..*</code>, annotiert mit den Stereotypen <code>«atpVariation,atpSplitable»</code>.\n</li><li>Unidirektionale Assoziation von <code>BswModuleEntity</code> zu <code>BswSchedulerNamePrefix</code>: Rollenname <code>+schedulerNamePrefix</code>, Multiplizität <code>0..1</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell-Strukturdiagramm; es stellt keine Laufzeit- oder Sequenzabläufe dar. Es definiert deklarative Kardinalitäten und Zuordnungen, die zur Entwurfszeit und während der Codegenerierung (insbesondere RTE-/BSW-Scheduler-Generierung) ausgewertet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für die AUTOSAR-Modellierung von BSW-Modulbeschreibungen:</p>\n<ul class=\"fig-list\"><li>Ein <code>BswInternalBehavior</code> aggregiert mindestens eine <code>BswModuleEntity</code> (<code>1..*</code>) und optional mehrere <code>BswSchedulerNamePrefix</code>-Definitionen (<code>0..*</code>).\n</li><li>Beide Kompositionen unterstützen sowohl Variabilität als auch Splitbarkeit über mehrere ARXML-Dateifragmente hinweg (<code>«atpVariation,atpSplitable»</code>).\n</li><li>Eine <code>BswModuleEntity</code> kann optional genau einen spezifischen <code>BswSchedulerNamePrefix</code> (<code>0..1</code>) referenzieren.\n</li><li>BSW-Scheduler-Präfixe dürfen keine nach außen sichtbaren Schnittstellenbezeichner oder Modulkürzel (<code>BswModuleEntry.shortName</code>) überschreiben, sondern dienen der Namensbildung interner Scheduler-Artefakte.\n</li></ul>"}], "trans": [{"from": "FIG-9f607bf36afa0f30", "to": "FIG-6fdb09b6d7409adc", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-6fdb09b6d7409adc", "to": "FIG-b81f108b9929e2a3", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Stereotyp an der Komposition von <code>BswInternalBehavior</code> zu <code>BswModuleEntity</code> (<code>+entity</code>): erweitert von <code>«atpVariation»</code> auf <code>«atpVariation,atpSplitable»</code>.\n</li><li>Stereotyp an der Komposition von <code>BswInternalBehavior</code> zu <code>BswSchedulerNamePrefix</code> (<code>+schedulerNamePrefix</code>): erweitert von <code>«atpVariation»</code> auf <code>«atpVariation,atpSplitable»</code>.\n</li></ul>"}]};
